        Some(etag.as_str()),
    )
    .await;
    assert_eq!(delete_status, StatusCode::OK, "multiple EXDATEs must not conflict");
    assert!(delete_response.contains("EXDATE:20260116T000000Z"));
    assert!(delete_response.contains("EXDATE:20260118T000000Z"));

    // Both deletions must be persisted.
    let deleted_count: i64 = sqlx::query_scalar(
        "SELECT COUNT(*) FROM event_recurrence_exceptions
