if is_existing_recurring && !incoming.exdates.is_empty() {
    let mut expected_version = event.version + 1;
    for exdate in &incoming.exdates {
        let result = match exdate {
            crate::ics::NormalizedDateValue::Timed(dt) => event_service
                .delete_occurrence(
                    session.user_id,
                    false,
                    calendar.calendar_id,
                    resource.event_id,
                    dt.timestamp(),
                    expected_version,
                )
                .await,
            crate::ics::NormalizedDateValue::AllDay(date) => event_service
                .delete_all_day_occurrence(
                    session.user_id,
                    false,
                    calendar.calendar_id,
                    resource.event_id,
                    &date.format("%Y-%m-%d").to_string(),
                    expected_version,
                )
                .await,
        };
        match result {
            Ok(projection) => {
                if let Some(v) = projection.version {
                    expected_version = v;
                }
            }
            Err(_) => return dav_server_error(),
        }
    }
